CREATE TABLE carrier_capacity_limits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,carrier_service_id uuid NOT NULL,warehouse_id uuid NOT NULL,effective_from date NOT NULL,effective_to date,max_shipments integer NOT NULL CHECK(max_shipments>0),max_units numeric(18,6) NOT NULL CHECK(max_units>0),response_sla_minutes integer NOT NULL DEFAULT 60 CHECK(response_sla_minutes BETWEEN 5 AND 10080),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id),FOREIGN KEY(company_id,carrier_service_id) REFERENCES carrier_services(company_id,id),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id),CHECK(effective_to>=effective_from),UNIQUE(company_id,carrier_service_id,warehouse_id,effective_from));
CREATE TABLE carrier_capacity_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,assignment_id uuid NOT NULL REFERENCES order_carrier_assignments(id) ON DELETE CASCADE,capacity_limit_id uuid NOT NULL REFERENCES carrier_capacity_limits(id) ON DELETE RESTRICT,service_date date NOT NULL,shipment_units numeric(18,6) NOT NULL CHECK(shipment_units>0),status text NOT NULL DEFAULT 'reserved' CHECK(status IN('reserved','consumed','released')),reserved_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,UNIQUE(company_id,assignment_id));
CREATE TABLE carrier_tender_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,assignment_id uuid NOT NULL REFERENCES order_carrier_assignments(id) ON DELETE CASCADE,attempt_number integer NOT NULL CHECK(attempt_number>0),carrier_service_id uuid NOT NULL,capacity_reservation_id uuid REFERENCES carrier_capacity_reservations(id) ON DELETE SET NULL,status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','accepted','rejected','expired','withdrawn')),submitted_at timestamptz NOT NULL DEFAULT now(),response_due_at timestamptz NOT NULL,responded_at timestamptz,response_note text,created_by uuid REFERENCES users(id),FOREIGN KEY(company_id,carrier_service_id) REFERENCES carrier_services(company_id,id),UNIQUE(company_id,assignment_id,attempt_number));
CREATE VIEW carrier_capacity_utilization WITH(security_invoker=true) AS SELECT l.company_id,l.id capacity_limit_id,l.carrier_service_id,l.warehouse_id,d.service_date,l.max_shipments,l.max_units,count(r.id)FILTER(WHERE r.status IN('reserved','consumed')) reserved_shipments,coalesce(sum(r.shipment_units)FILTER(WHERE r.status IN('reserved','consumed')),0) reserved_units,greatest(0,l.max_shipments-count(r.id)FILTER(WHERE r.status IN('reserved','consumed'))) available_shipments,greatest(0,l.max_units-coalesce(sum(r.shipment_units)FILTER(WHERE r.status IN('reserved','consumed')),0)) available_units FROM carrier_capacity_limits l CROSS JOIN LATERAL(SELECT generate_series(greatest(current_date,l.effective_from),least(current_date+30,l.effective_to),'1 day')::date service_date)d LEFT JOIN carrier_capacity_reservations r ON r.capacity_limit_id=l.id AND r.service_date=d.service_date WHERE l.active GROUP BY l.company_id,l.id,l.carrier_service_id,l.warehouse_id,d.service_date,l.max_shipments,l.max_units;
CREATE VIEW carrier_tender_kpis WITH(security_invoker=true) AS SELECT a.company_id,o.warehouse_id,t.carrier_service_id,date_trunc('month',t.submitted_at)::date activity_month,count(*) tenders,count(*)FILTER(WHERE t.status='accepted') accepted,count(*)FILTER(WHERE t.status='rejected') rejected,count(*)FILTER(WHERE t.status='expired') expired,count(*)FILTER(WHERE t.attempt_number>1) fallback_attempts,100.0*count(*)FILTER(WHERE t.status='accepted')/nullif(count(*),0) acceptance_rate,avg(extract(epoch FROM(t.responded_at-t.submitted_at))/60)FILTER(WHERE t.responded_at IS NOT NULL) average_response_minutes FROM carrier_tender_attempts t JOIN order_carrier_assignments a ON a.id=t.assignment_id JOIN sales_orders o ON o.id=a.order_id GROUP BY a.company_id,o.warehouse_id,t.carrier_service_id,date_trunc('month',t.submitted_at)::date;
ALTER TABLE carrier_capacity_limits ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_capacity_limits FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_capacity_reservations ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_capacity_reservations FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_tender_attempts ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_tender_attempts FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_carrier_capacity_limits ON carrier_capacity_limits USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_capacity_reservations ON carrier_capacity_reservations USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_tender_attempts ON carrier_tender_attempts USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON carrier_capacity_limits,carrier_capacity_reservations,carrier_tender_attempts TO stockflow_app;GRANT SELECT ON carrier_capacity_utilization,carrier_tender_kpis TO stockflow_app;CREATE INDEX carrier_capacity_lookup_idx ON carrier_capacity_limits(company_id,warehouse_id,carrier_service_id,effective_from,effective_to);CREATE INDEX carrier_tender_deadline_idx ON carrier_tender_attempts(company_id,status,response_due_at);
